sealed trait OrderEvent { def occurredOn: Instant }
final case class OrderPlaced(orderId: Long, occurredOn: Instant) extends OrderEvent

def dispatch(e: OrderEvent): Unit = e match {
  case OrderPlaced(id, _) => stock.reserve(id)   // non-exhaustive => compiler warning
}

